/* =====================================================================
   ui_studio.js : configurator, design catalogue, communication, setup,
                  users & roles, backups
   ===================================================================== */
/* ---------------- configurator ---------------- */
VIEWS.config = {perm: 'config', title: 'Configurator', fn: () => {
  const tab = UI.ctab || 'designs';
  return `<div class="row ac"><div><h1>Configurator</h1><div class="sub">Garment types (measurements, specifications, materials and their own production workflow), production stages, and the design catalogue.</div></div></div>
  <div class="tabs">${[['designs', `Design catalogue (${coll('designs').length})`], ['types', `Garment types & workflows (${coll('templates').length})`], ['stages', 'Production stages']].map(([k, l]) => `<button class="${tab === k ? 'on' : ''}" onclick="UI.ctab='${k}';render()">${l}</button>`).join('')}</div>
  ${({designs: confDesigns, types: confTypes, stages: confStages}[tab])()}`;
}};
function confDesigns(){
  const q = (UI.dq || '').toLowerCase(), ft = UI.dt || '', fs = UI.ds || '';
  const cats = [...new Set(coll('templates').map(t => t.category || 'Other'))];
  const L = coll('designs').filter(d => (!ft || (ft.startsWith('cat:') ? (tpl(d.tplId)?.category || 'Other') === ft.slice(4) : d.tplId === ft)) && (!fs || d.style === fs) && (!q || `${d.name} ${d.code} ${d.tags} ${d.style}`.toLowerCase().includes(q)));
  return `<div class="row ac" style="margin-bottom:12px"><select style="width:auto" onchange="UI.dt=this.value;render()">${opt('', 'All garment categories', ft)}${cats.map(c => `<optgroup label="${h(c)}">${opt('cat:' + c, 'All ' + c, ft)}${coll('templates').filter(t => (t.category || 'Other') === c).map(t => opt(t.id, t.name, ft)).join('')}</optgroup>`).join('')}</select>
    <select style="width:auto" onchange="UI.ds=this.value;render()">${opt('', 'All embroidery styles', fs)}${(ST().embStyles || []).map(s => opt(s, s, fs)).join('')}</select>
    <input style="max-width:240px" placeholder="Search name, code, tag" value="${v(UI.dq)}" onchange="UI.dq=this.value;render()"><span class="sp"></span><button class="pri" onclick="newDesign()">+ New design</button></div>
  ${L.length ? designGrid(L, null) : '<div class="card empty">No designs match.</div>'}`;
}
function designGrid(list, act){
  return `<div class="dgrid">${list.map(d => { const c = dzCover(d), on = act ? act.replace('ID', d.id) : `go('design-${d.id}')`, uses = coll('garments').filter(g => g.design?.catalogId === d.id).length;
    return `<div class="dcard" onclick="${on}"><div class="dimg" ${c ? `data-media="${h(c)}"` : ''}>✦</div><div class="b"><div class="row ac" style="gap:6px"><b>${h(d.name)}</b>${d.active === false ? '<span class="chip c-mut">inactive</span>' : ''}</div><div class="muted" style="font-size:12px">${h(d.code)} · ${h(tpl(d.tplId)?.name || '—')}</div><div style="margin-top:4px">${d.style ? `<span class="chip c-gold">${h(d.style)}</span>` : ''} ${uses ? `<span class="chip c-mut">${uses} order${uses > 1 ? 's' : ''}</span>` : ''}</div></div></div>`; }).join('')}</div>`;
}
function newDesign(){ const d = {id: uid('d'), name: 'New design', code: 'DSN-' + (coll('designs').length + 101), tplId: coll('templates')[0]?.id || '', style: '', tags: '', description: '', samples: [], sketches: [], stencils: [], renders: [], spin: [], model: '', cover: '', addComps: [], addTasks: [], active: true, created: nowISO(), history: []}; coll('designs').push(d); save(); go('design-' + d.id); }
VIEWS.design = {perm: 'config', title: 'Design', parent: 'config', fn: (id) => {
  const k = coll('designs').findIndex(d => d.id === id); if(k < 0) return '<div class="card">Design not found.</div>';
  const d = DB.designs[k], P = `designs.${k}`; ['sketches'].forEach(f => d[f] = d[f] || []);
  const up = (field, label, accept, multi) => `<label class="btn sm" style="margin:0;color:var(--ink)">⬆ ${label}<input type="file" accept="${accept || 'image/*'}" ${multi === false ? '' : 'multiple'} style="display:none" onchange="upDesignMedia('${d.id}','${field}',this)"></label>`;
  const sec = (field, title, hint) => `<div class="card"><div class="row ac"><h3 style="margin:0">${title} (${d[field].length})</h3><span class="sp"></span>${up(field, 'Upload')}</div><div class="hint" style="margin:2px 0 8px">${hint}</div>${d[field].length ? `<div class="thumbs">${d[field].map((m, j) => `<div class="thumb" data-media="${h(m)}" onclick='lightboxIds(${h(JSON.stringify(d[field]))},${j})'>${dzCover(d) === m ? '<span class="cap">★ cover</span>' : ''}<button class="tbtn" onclick="event.stopPropagation();rmDesignMedia('${d.id}','${field}',${j})">✕</button><button class="tbtn" style="right:auto;left:4px;color:var(--gold)" title="Use as cover" onclick="event.stopPropagation();setCover('${d.id}','${h(m)}')">★</button></div>`).join('')}</div>` : '<div class="empty" style="padding:14px">Nothing uploaded yet</div>'}</div>`;
  const used = coll('garments').filter(g => g.design?.catalogId === d.id);
  if(d.model) ensureMV();
  return `<div class="row ac"><div><div class="muted"><a href="#config">← Catalogue</a></div><h1>${h(d.name)}</h1><div class="sub">${h(d.code)} · ${h(tpl(d.tplId)?.name || '')} · ${h(d.style || 'no style set')} · used on ${used.length} garment(s)</div></div><span class="sp"></span><button onclick="dupDesign('${d.id}')">Duplicate</button><button class="danger" onclick="delDesign('${d.id}')">Delete</button></div>
  <div class="card"><div class="fgrid"><div><label>Design name</label><input data-root="DB" data-p="${P}.name" value="${v(d.name)}"></div><div><label>Code</label><input data-root="DB" data-p="${P}.code" value="${v(d.code)}"></div><div><label>Garment type</label><select data-root="DB" data-p="${P}.tplId" data-r>${coll('templates').map(t => opt(t.id, t.name, d.tplId)).join('')}</select></div><div><label>Embroidery style</label><select data-root="DB" data-p="${P}.style" data-r>${opt('', '—', d.style)}${(ST().embStyles || []).map(s => opt(s, s, d.style)).join('')}</select></div><div><label>Tags</label><input data-root="DB" data-p="${P}.tags" value="${v(d.tags)}"></div><div><label>&nbsp;</label><label class="inline"><input type="checkbox" data-root="DB" data-p="${P}.active" ${d.active !== false ? 'checked' : ''}> Active in catalogue</label></div><div class="full"><label>Description</label><textarea rows="2" data-root="DB" data-p="${P}.description">${h(d.description)}</textarea></div></div></div>
  <h3>Primary references — actual photos, sketches and approved khaka come first</h3>
  <div class="grid3">${sec('samples', 'Actual garment photos', 'Photos of finished pieces made with this design.')}${sec('sketches', 'Sketches', 'Design sketches and approved drawings.')}${sec('stencils', 'Khaka / tracing / stencils', 'Tracing patterns for artisans — printed on the artisan sheet.')}</div>
  <details class="card" ${d.renders.length || d.spin.length || d.model ? 'open' : ''}><summary><b>Optional views — 3D and 360°</b></summary>
    <div class="grid2" style="margin-top:12px"><div><div class="row ac"><h3 style="margin:0">3D</h3><span class="sp"></span>${up('renders', '3D renders')}${up('model', '.glb model', '.glb', false)}</div>
      ${d.model ? `<model-viewer data-media="${h(d.model)}" camera-controls auto-rotate shadow-intensity="1" style="width:100%;height:300px;background:#f4eef0;border-radius:10px;display:block;margin-top:8px"></model-viewer><button class="sm ghost danger" onclick="design('${d.id}').model='';save();render()">Remove model</button>` : ''}
      ${d.renders.length ? `<div class="thumbs" style="margin-top:8px">${d.renders.map((m, j) => `<div class="thumb" data-media="${h(m)}" onclick='lightboxIds(${h(JSON.stringify(d.renders))},${j})'><button class="tbtn" onclick="event.stopPropagation();rmDesignMedia('${d.id}','renders',${j})">✕</button></div>`).join('')}</div>` : ''}<div class="hint">The interactive 3D viewer loads from the internet.</div></div>
    <div><div class="row ac"><h3 style="margin:0">360° view (${d.spin.length} frames)</h3><span class="sp"></span>${up('spin', 'Upload frames')}${d.spin.length ? `<button class="sm ghost danger" onclick="ask('Remove all 360° frames?',()=>{design('${d.id}').spin=[];save();render()})">Clear</button>` : ''}</div>${d.spin.length ? spinHTML(d.spin, 'sp_' + d.id) : '<div class="empty">Upload 12–36 photos taken while turning the dress form.</div>'}</div></div></details>
  <div class="card"><h3>Design add-ons — offered when this design is chosen for an order</h3><div class="hint" style="margin-bottom:8px">Extra materials and extra work (embroidery hours, tracing, handwork) that this design needs on top of the garment type's default plan.</div>
    <h3>Extra materials</h3>${compTable(d.addComps, P + '.addComps', 'DB')}<h3 style="margin-top:14px">Extra work</h3>${stepsTable(d.addTasks, P + '.addTasks', 'DB')}</div>
  <div class="card"><h3>Orders using this design</h3>${used.length ? used.map(g => `<div style="padding:5px 0;border-bottom:1px solid var(--line)"><a href="#garment-${g.id}"><b>${h(g.no)}</b> ${h(g.title)}</a> · ${h(cust(g.customerId)?.name)} ${gChip(g)}</div>`).join('') : '<div class="empty">Not used yet.</div>'}</div>`;
}};
async function upDesignMedia(did, field, inp){
  const d = design(did), files = [...inp.files]; inp.value = ''; if(!files.length) return;
  if(field === 'model'){ const f = files[0]; if(!/\.glb$/i.test(f.name)) return toast('3D model must be a .glb file', 'bad'); if(f.size > 20e6) return toast('Model is larger than 20 MB', 'bad'); d.model = await mediaPut(f); save(); render(); return; }
  toast(`Processing ${files.length} file(s)…`);
  const ids = await uploadImages(files, field === 'spin' ? 1000 : 1600); d[field].push(...ids); save(); render(); if(ids.length) toast(`${ids.length} file(s) added`, 'ok');
}
function rmDesignMedia(did, field, j){ ask('Remove this image?', () => { const d = design(did), id = d[field].splice(j, 1)[0]; if(d.cover === id) d.cover = ''; save(); render(); }); }
function setCover(did, id){ design(did).cover = id; save(); render(); }
function dupDesign(did){ const d = clone(design(did)); d.id = uid('d'); d.name += ' (copy)'; d.code += '-B'; coll('designs').push(d); save(); go('design-' + d.id); }
function delDesign(did){ const n = coll('garments').filter(g => g.design?.catalogId === did).length; ask(`Delete this design?${n ? ` ${n} garment(s) keep their own design files.` : ''}`, () => { DB.designs = coll('designs').filter(d => d.id !== did); save(); go('config'); }); }
function ensureMV(){ if(window.customElements && customElements.get('model-viewer')) return; if(document.getElementById('mvjs')) return; const s = document.createElement('script'); s.type = 'module'; s.id = 'mvjs'; s.src = 'https://cdn.jsdelivr.net/npm/@google/model-viewer@3.4.0/dist/model-viewer.min.js'; document.head.appendChild(s); }
function spinHTML(frames, id){ return `<div class="spin" id="${id}" data-frames='${h(JSON.stringify(frames))}' style="margin-top:8px"><img alt="360 degree view" draggable="false"><div class="spin-ui"><button class="sm spin-play" onclick="spinPlay('${id}')">▶ Rotate</button><input type="range" min="0" max="${frames.length - 1}" value="0" oninput="spinTo('${id}',+this.value)"><span class="muted" style="font-size:12px">Drag to turn</span></div></div>`; }
function initSpins(root){
  (root || document).querySelectorAll('.spin:not([data-init])').forEach(async el => {
    el.dataset.init = '1'; const frames = JSON.parse(el.dataset.frames || '[]'), urls = await Promise.all(frames.map(mediaUrl)); el._urls = urls; el._i = 0;
    const img = el.querySelector('img'); img.src = urls[0] || ''; let down = null, start = 0;
    img.addEventListener('pointerdown', e => { down = e.clientX; start = el._i; try{ img.setPointerCapture(e.pointerId); }catch(_){} spinStop(el); e.preventDefault(); });
    img.addEventListener('pointermove', e => { if(down == null) return; const step = Math.max(4, img.clientWidth / (urls.length * 1.2)); spinSet(el, start + Math.round((down - e.clientX) / step)); });
    const up = () => { down = null; }; img.addEventListener('pointerup', up); img.addEventListener('pointercancel', up);
  });
}
function spinSet(el, i){ const n = el._urls.length; if(!n) return; i = ((i % n) + n) % n; el._i = i; el.querySelector('img').src = el._urls[i]; const r = el.querySelector('input[type=range]'); if(r) r.value = i; }
function spinTo(id, i){ const el = document.getElementById(id); if(el && el._urls){ spinStop(el); spinSet(el, i); } }
function spinStop(el){ if(el._t){ clearInterval(el._t); el._t = null; const b = el.querySelector('.spin-play'); if(b) b.textContent = '▶ Rotate'; } }
function spinPlay(id){ const el = document.getElementById(id); if(!el || !el._urls) return; if(el._t) return spinStop(el); el._t = setInterval(() => { if(!document.body.contains(el)){ clearInterval(el._t); return; } spinSet(el, el._i + 1); }, 90); el.querySelector('.spin-play').textContent = '⏸ Pause'; }

function confTypes(){
  const k = Math.max(0, Math.min(UI.ttab || 0, coll('templates').length - 1)), t = DB.templates[k];
  return `<div class="card"><div class="row ac">${coll('templates').map((x, j) => `<button class="sm ${j === k ? 'pri' : ''}" onclick="UI.ttab=${j};render()">${h(x.name)}</button>`).join('')}<span class="sp"></span><button class="sm" onclick="addTpl()">+ New garment type</button>${t ? `<button class="sm" onclick="dupTpl(${k})">Duplicate</button><button class="sm danger" onclick="rmTpl(${k})">Delete</button>` : ''}</div></div>
  ${t ? `<div class="card"><div class="fgrid"><div><label>Garment type name</label><input data-root="DB" data-p="templates.${k}.name" value="${v(t.name)}"></div><div><label>Category</label><input data-root="DB" data-p="templates.${k}.category" value="${v(t.category)}" placeholder="Women, Men, Bridal, Kids…"></div></div></div>
  <div class="grid2"><div class="card"><h3>Measurement sheet(s) for this article</h3><div class="row" style="gap:12px;flex-wrap:wrap">${Object.entries(CHARTS).map(([ck, C2]) => `<label class="inline"><input type="checkbox" ${(t.charts || []).includes(ck) ? 'checked' : ''} onchange="setCharts(${k},'${ck}',this.checked)"> ${h(C2.name)} (${C2.items.length})</label>`).join('')}</div>
    <div class="hint">The order taker sees one diagram per measurement, in the same order as the studio's printed sheet. Pick two for a set (e.g. Top + Bottom for a salwar suit).</div>
    ${(t.charts || []).length ? `<div class="mcards" style="margin-top:10px;grid-template-columns:repeat(auto-fill,minmax(110px,1fr))">${t.charts.flatMap(ck => CHARTS[ck].items.map(it => `<div class="mcard view"><div class="mhead"><span class="mno">${it[0]}</span><span class="mlab" style="font-size:11px">${h(it[1])}</span></div><div class="msvg">${measSVG(ck, it)}</div></div>`)).join('')}</div>`
    : `<label style="margin-top:10px">Custom measurement list</label><textarea rows="12" onchange="setFields(${k},this.value)" style="font-family:ui-monospace,Menlo,monospace;font-size:12.5px">${h(t.fields.map(f => `${f.sec} | ${f.label}`).join('\n'))}</textarea><div class="hint">One per line: <b>Section | Measurement</b>. Used when no sheet is ticked (e.g. saree finishing).</div>`}</div>
  <div class="card"><h3>Garment specifications</h3><textarea rows="16" onchange="setSpecs(${k},this.value)" style="font-family:ui-monospace,Menlo,monospace;font-size:12.5px">${h((t.specs || []).map(s => `${s.label} | ${s.options.join(' / ')}`).join('\n'))}</textarea><div class="hint">One per line: <b>Specification | option / option / …</b> (e.g. "Back neck | Deep U / Dori back"). Options are suggestions; staff can type anything.</div></div></div>
  <div class="card"><h3>Production workflow for ${h(t.name)}</h3><div class="hint" style="margin:-4px 0 8px">The default steps each new garment of this type starts with. Mark steps optional with Skip on the garment; add repeats and corrections there.</div>${stepsTable(t.workflow, `templates.${k}.workflow`, 'DB')}</div>
  <div class="card"><h3>Default pieces & materials</h3>${compTable(t.components, `templates.${k}.components`, 'DB')}</div>` : ''}`;
}
function setCharts(k, ck, on){ const t = DB.templates[k]; t.charts = (t.charts || []).filter(x => x !== ck); if(on) t.charts.push(ck); t.charts.sort((a, b) => Object.keys(CHARTS).indexOf(a) - Object.keys(CHARTS).indexOf(b)); if(t.charts.length) t.fields = chartFields(t.charts); else { delete t.charts; t.fields = F('Main', 'Length,Chest,Waist'); } save(); render(); toast('Measurement sheets updated', 'ok'); }
function setFields(k, text){ DB.templates[k].fields = text.split('\n').map(l => l.trim()).filter(Boolean).map(l => { const [a, b] = l.includes('|') ? l.split('|').map(x => x.trim()) : ['General', l]; return {k: slug(a + '_' + b), label: b, sec: a}; }); save(); render(); toast('Measurement fields updated', 'ok'); }
function setSpecs(k, text){ DB.templates[k].specs = text.split('\n').map(l => l.trim()).filter(Boolean).map(l => { const [a, b] = l.split('|').map(x => x.trim()); return {k: slug(a), label: a, options: (b || '').split('/').map(x => x.trim()).filter(Boolean)}; }); save(); render(); toast('Specifications updated', 'ok'); }
function addTpl(){ DB.templates.push({id: uid('t'), name: 'New garment type', category: '', charts: ['top'], fields: chartFields(['top']), specs: [], components: [], workflow: [W('cut', 'Whole garment', 1, {rate: 150}), W('stitch', 'Assembly', 2, {rate: 400, hours: 3}), W('qc', 'Final QC', 3, {hours: 0.5})]}); UI.ttab = DB.templates.length - 1; save(); render(); }
function dupTpl(k){ const t = clone(DB.templates[k]); t.id = uid('t'); t.name += ' (copy)'; DB.templates.push(t); UI.ttab = DB.templates.length - 1; save(); render(); }
function rmTpl(k){ const t = DB.templates[k]; if(coll('garments').some(g => g.tplId === t.id)) return toast('Used by garments — rename or duplicate instead', 'bad'); ask(`Delete garment type "${t.name}"?`, () => { DB.templates.splice(k, 1); UI.ttab = 0; save(); render(); }); }
function confStages(){
  return `<div class="card"><div class="hint" style="margin-bottom:10px"><b>Kind</b>: in-house work, outside (vendor), trial or QC. <b>Milestone</b> decides which target date a step follows. <b>Bill head</b> decides where its cost appears on the invoice.</div>
  <table class="ed stack"><thead><tr><th>Stage</th><th>Kind</th><th>Milestone</th><th>Bill head</th><th style="width:110px">Default rate ₹</th><th></th></tr></thead><tbody>
  ${coll('stages').map((s, j) => `<tr><td><input data-root="DB" data-p="stages.${j}.name" value="${v(s.name)}"></td><td><select data-root="DB" data-p="stages.${j}.kind">${[['work', 'In-house work'], ['external', 'Outside / vendor'], ['trial', 'Trial'], ['qc', 'QC']].map(([a, b]) => opt(a, b, s.kind)).join('')}</select></td><td><select data-root="DB" data-p="stages.${j}.group">${GROUPS.filter(([g]) => g !== 'delivery').map(([a, b]) => opt(a, b, s.group)).join('')}</select></td><td><select data-root="DB" data-p="stages.${j}.head">${ST().heads.map(x => opt(x.id, x.name, s.head)).join('')}</select></td><td><input type="number" data-root="DB" data-p="stages.${j}.rate" value="${v(s.rate)}"></td><td>${['cut', 'emb', 'stitch', 'trial', 'qc', 'alter'].includes(s.id) ? '' : `<button class="sm ghost danger" onclick="rmStage(${j})">✕</button>`}</td></tr>`).join('')}</tbody></table>
  <button class="sm" style="margin-top:8px" onclick="DB.stages.push({id:uid('s'),name:'New stage',kind:'work',group:'finishing',head:'basic_stitching',rate:0});save();render()">+ Add stage</button></div>`;
}
function rmStage(j){ const s = DB.stages[j]; if(coll('garments').some(g => g.steps.some(x => x.stageId === s.id)) || coll('templates').some(t => t.workflow.some(x => x.stageId === s.id))) return toast('Stage is in use', 'bad'); ask(`Remove stage "${s.name}"?`, () => { DB.stages.splice(j, 1); save(); render(); }); }

/* ---------------- communication ---------------- */
const EVENTS = {order_created: 'Order confirmation', trial: 'Trial reminder', update: 'Delivery update', delay: 'Delay notice', ready: 'Ready for pickup', delivered: 'Delivered – thank you', payment: 'Payment received', payment_reminder: 'Payment reminder', general: 'General / festive', admin_alert: 'Alert to owner'};
const PH = ['customer_name', 'customer_first', 'order_no', 'garment', 'garment_list', 'garment_status', 'delivery_date', 'expected_date', 'trial_date', 'total', 'paid', 'balance', 'amount', 'receipt_no', 'invoice_no', 'shop_name', 'shop_mobile', 'shop_address', 'shop_website', 'upi_id', 'today', 'alert_title', 'alert_detail'];
let CMP = null;
function msgCtx(o, c, g, extra){
  const s = ST(), T = o ? orderTotals(o) : null, n = x => num(x).toLocaleString('en-IN', {maximumFractionDigits: 2}), gs = o ? activeG(o) : [], sc = sched();
  const gl = gs.map(x => `• ${x.title} — delivery ${fmtD(x.deliveryDate)}`).join('\n'), gst = gs.map(x => `• ${x.title}: ${gStageLabel(x)}${gLive(x) && sc.G[x.id] ? ' (expected ' + fmtD(sc.G[x.id].ready) + ')' : ''}`).join('\n');
  const iv = o ? coll('invoices').filter(i => i.orderId === o.id).pop() : null, nx = gs.filter(gLive).map(x => x.deliveryDate).sort()[0];
  return Object.assign({customer_name: c?.name || '', customer_first: (c?.name || '').split(' ')[0], order_no: o?.no || '', garment: g ? g.title : gs.map(x => x.title).join(', '), garment_list: gl, garment_status: gst, delivery_date: fmtD(g ? g.deliveryDate : nx || o?.deliveryDate), expected_date: fmtD(g ? sc.G[g.id]?.ready : ''), trial_date: '', total: T ? n(T.total) : '', paid: T ? n(T.paid) : '', balance: T ? n(Math.max(0, T.bal)) : '', amount: '', receipt_no: '', invoice_no: iv?.no || '', shop_name: s.shop, shop_mobile: s.phone, shop_address: s.address, shop_website: s.website || '', upi_id: s.upiId || '', today: fmtD(todayISO()), alert_title: '', alert_detail: ''}, extra || {});
}
const fillMsg = (body, ctx) => String(body || '').replace(/\{(\w+)\}/g, (m, k) => k in ctx ? ctx[k] : m);
function smsInfo(t){ const uni = /[^\x00-\x7F]/.test(t), per = uni ? (t.length > 70 ? 67 : 70) : (t.length > 160 ? 153 : 160), seg = Math.max(1, Math.ceil(t.length / per)); return `${t.length} characters · ${seg} SMS part${seg > 1 ? 's' : ''}${uni ? ' (Unicode — emoji and ₹ shorten each part)' : ''}`; }
function adminMsg(a){ const t = coll('msgTemplates').find(x => x.event === 'admin_alert' && x.active !== false), o = a.oid ? ord(a.oid) : null, g = a.gid ? gar(a.gid) : null; return fillMsg(t ? t.body : '⚠ {shop_name}: {alert_title}\n{alert_detail}', msgCtx(o, o ? cust(o.customerId) : null, g, {alert_title: a.title, alert_detail: a.detail})); }
function autoMsg(oid, ev, extra, gid){ if(!can('comms')) return; const t = coll('msgTemplates').find(x => x.event === ev && x.active !== false && x.auto); if(t) openCompose(oid, ev, null, t.id, gid, extra); }
function openCompose(oid, ev, cid, tplId, gid, extra){
  const o = oid ? ord(oid) : null, c = cust(cid || o?.customerId), g = gid ? gar(gid) : null; if(!c) return toast('No customer for this message', 'bad');
  const list = coll('msgTemplates').filter(t => t.active !== false && t.event !== 'admin_alert');
  const t = list.find(x => x.id === tplId) || list.find(x => x.event === ev) || list[0];
  CMP = {oid: o?.id || null, cid: c.id, gid: g?.id || null, tplId: t?.id || '', extra: extra || {}, ev};
  openModal(`<div class="mbar"><b>Message ${h(c.name)}</b>${o ? `<span class="muted">· ${h(o.no)}${g ? ' · ' + h(g.title) : ''}</span>` : ''}<span class="sp"></span><button onclick="closeModal()">Close</button></div>
  <div class="row"><div class="f"><label>Preset</label><select id="cmpTpl" onchange="cmpTpl(this.value)">${list.map(x => opt(x.id, `${x.name} · ${x.channel === 'sms' ? 'SMS' : x.channel === 'both' ? 'WhatsApp + SMS' : 'WhatsApp'}`, CMP.tplId)).join('')}</select></div><div class="f" style="max-width:220px"><label>Mobile</label><input id="cmpTo" value="${v(c.phone)}" oninput="cmpLinks()"></div></div>
  <div style="margin-top:10px"><label>Message (edit before sending)</label><textarea id="cmpText" rows="8" oninput="cmpLinks()">${h(t ? fillMsg(t.body, msgCtx(o, c, g, CMP.extra)) : '')}</textarea><div class="hint" id="cmpCount"></div></div>
  <div class="row" style="margin-top:10px"><a class="btn pri" id="cmpWA" target="_blank" rel="noopener" onclick="logSend('WhatsApp')">💬 Open in WhatsApp</a><a class="btn" id="cmpSMS" target="_blank" rel="noopener" onclick="logSend('SMS')">✉ Open in SMS</a><button onclick="copyText('cmpText');logSend('Copied')">📋 Copy</button></div>
  <div class="hint">Opens WhatsApp or the SMS app with the message filled in — you press send. Every message is saved under the order.</div>`);
  cmpLinks();
}
function cmpTpl(id){ const t = coll('msgTemplates').find(x => x.id === id); CMP.tplId = id; document.getElementById('cmpText').value = fillMsg(t.body, msgCtx(ord(CMP.oid), cust(CMP.cid), gar(CMP.gid), CMP.extra)); cmpLinks(); }
function cmpLinks(){ const txt = document.getElementById('cmpText').value, to = document.getElementById('cmpTo').value; document.getElementById('cmpWA').href = waLink(to, txt); document.getElementById('cmpSMS').href = smsLink(to, txt); document.getElementById('cmpCount').textContent = smsInfo(txt); }
function logSend(ch){
  const txt = document.getElementById('cmpText').value, t = coll('msgTemplates').find(x => x.id === CMP.tplId);
  coll('msgLog').push({id: uid('ml'), at: nowISO(), orderId: CMP.oid, garmentId: CMP.gid, customerId: CMP.cid, to: document.getElementById('cmpTo').value, channel: ch, tplId: CMP.tplId, tplName: t?.name || 'Custom', text: txt, by: meName()});
  const o = CMP.oid && ord(CMP.oid); if(o) o.history.push({at: nowISO(), by: meName(), action: `${ch === 'Copied' ? 'Message copied' : ch + ' message opened'}: ${t?.name || 'custom'}`, changes: []});
  save(); if(ch !== 'Copied') toast(`${ch} opened — saved in the order's communication history`, 'ok');
}
VIEWS.comms = {perm: 'comms', title: 'Communication', fn: () => {
  const tab = UI.mtab || 'templates', L = coll('msgTemplates'), k = Math.max(0, Math.min(UI.msel || 0, L.length - 1)), t = L[k];
  const head = `<div class="row ac"><div><h1>Communication</h1><div class="sub">Preset WhatsApp and SMS messages. Order details fill in automatically; every message is saved under its order.</div></div><span class="sp"></span><button onclick="quickCompose()">💬 New message</button></div>
  <div class="tabs">${[['templates', `Presets (${L.length})`], ['log', `Sent log (${coll('msgLog').length})`], ['test', 'Test sending & automation']].map(([x, l]) => `<button class="${tab === x ? 'on' : ''}" onclick="UI.mtab='${x}';render()">${l}</button>`).join('')}</div>`;
  if(tab === 'log'){ const M = coll('msgLog').slice().reverse(); return head + `<div class="card">${M.length ? `<table class="stack"><thead><tr><th>When</th><th>Customer</th><th>Order</th><th>Channel</th><th>Preset</th><th>Message</th></tr></thead><tbody>${M.map(m => `<tr><td class="nowrap">${fmtDT(m.at)}<div class="muted" style="font-size:11.5px">${h(m.by || '')}</div></td><td>${h(cust(m.customerId)?.name || '—')}<div class="muted" style="font-size:11.5px">${h(m.to)}</div></td><td>${m.orderId && ord(m.orderId) ? `<a href="#order-${m.orderId}">${h(ord(m.orderId).no)}</a>` : '—'}</td><td><span class="chip ${m.channel === 'WhatsApp' ? 'c-ok' : m.channel === 'SMS' ? 'c-info' : 'c-mut'}">${h(m.channel)}</span></td><td>${h(m.tplName)}</td><td style="font-size:12.5px;white-space:pre-wrap;max-width:420px">${h(m.text.length > 200 ? m.text.slice(0, 200) + '…' : m.text)}</td></tr>`).join('')}</tbody></table>` : '<div class="empty">No messages yet.</div>'}</div>`; }
  if(tab === 'test'){ const s = ST(); return head + `<div class="grid2"><div class="card"><h3>Test the sending path</h3><p>Sends a test message to the owner's number so you can confirm WhatsApp and SMS open correctly on this device.</p><div class="row"><input id="testTo" value="${v(s.adminPhone || s.phone)}" placeholder="Mobile number" style="max-width:220px"><a class="btn pri" target="_blank" rel="noopener" href="${h(waLink(s.adminPhone || s.phone, 'Test message from ' + s.shop + ' order system ✅'))}" onclick="this.href=waLink(document.getElementById('testTo').value,'Test message from ${h(s.shop)} order system ✅');toast('If WhatsApp opened with the message, sending works on this device','ok')">💬 Test WhatsApp</a><a class="btn" target="_blank" rel="noopener" href="${h(smsLink(s.adminPhone || s.phone, 'Test from ' + s.shop))}" onclick="this.href=smsLink(document.getElementById('testTo').value,'Test from ${h(s.shop)}')">✉ Test SMS</a></div><div class="hint">Works on phones and on computers with WhatsApp Desktop / Web.</div></div>
    <div class="card"><h3>About fully automatic sending</h3><p class="muted" style="font-size:13.5px">Today each message opens ready to send and a person taps <b>Send</b> — reliable, free, and every message is logged. Sending with no tap at all (for example, reminders at 9 am every day) needs a paid gateway — <b>WhatsApp Business Platform</b> (via Meta or a partner like Gupshup, Interakt, Twilio) or an <b>SMS provider</b> such as MSG91 with DLT-registered templates — plus a small server to hold the API key securely. A browser page can't hold that key safely. The presets here are written so they can be registered as gateway templates later.</p></div></div>`; }
  const sampleO = coll('orders').find(o => o.status !== 'cancelled' && activeG(o).some(gLive)) || coll('orders')[0];
  return head + `<div class="grid2" style="grid-template-columns:300px minmax(0,1fr)"><div class="card" style="padding:8px">${L.map((x, j) => `<div style="padding:9px 10px;border-radius:8px;cursor:pointer;${j === k ? 'background:var(--accent-soft)' : ''}" onclick="UI.msel=${j};render()"><b>${h(x.name)}</b><div class="muted" style="font-size:12px">${h(EVENTS[x.event] || x.event)} · ${x.channel === 'both' ? 'WhatsApp + SMS' : x.channel === 'sms' ? 'SMS' : 'WhatsApp'}${x.auto ? ' · offered automatically' : ''}${x.active === false ? ' · off' : ''}</div></div>`).join('')}<button class="sm" style="margin:8px" onclick="DB.msgTemplates.push({id:uid('m'),name:'New preset',event:'general',channel:'whatsapp',auto:false,active:true,body:'Hi {customer_first}, '});UI.msel=DB.msgTemplates.length-1;save();render()">+ New preset</button></div>
  ${t ? `<div class="card"><div class="fgrid"><div><label>Preset name</label><input data-root="DB" data-p="msgTemplates.${k}.name" value="${v(t.name)}"></div><div><label>Used for</label><select data-root="DB" data-p="msgTemplates.${k}.event" data-r>${Object.entries(EVENTS).map(([e, l]) => opt(e, l, t.event)).join('')}</select></div><div><label>Channel</label><select data-root="DB" data-p="msgTemplates.${k}.channel">${opt('whatsapp', 'WhatsApp', t.channel)}${opt('sms', 'SMS', t.channel)}${opt('both', 'Both', t.channel)}</select></div></div>
    <div class="row ac" style="margin-top:10px"><label class="inline"><input type="checkbox" data-root="DB" data-p="msgTemplates.${k}.auto" ${t.auto ? 'checked' : ''}> Offer to send when this event happens</label><label class="inline"><input type="checkbox" data-root="DB" data-p="msgTemplates.${k}.active" ${t.active !== false ? 'checked' : ''}> Active</label><span class="sp"></span><button class="sm danger" onclick="ask('Delete this preset?',()=>{DB.msgTemplates.splice(${k},1);UI.msel=0;save();render()})">Delete</button></div>
    <label style="margin-top:10px">Message</label><textarea id="tplBody" rows="7" data-root="DB" data-p="msgTemplates.${k}.body" oninput="commsPrev()">${h(t.body)}</textarea>
    <div style="margin-top:6px">${PH.map(p => `<button class="sm" style="margin:2px;font-family:ui-monospace,monospace;font-size:11px" onclick="insPh('{${p}}')">{${p}}</button>`).join('')}</div>
    <h3 style="margin-top:14px">Preview${sampleO ? ' · ' + h(sampleO.no) : ''}</h3><div id="tplPrev" style="white-space:pre-wrap;background:#dcf8c6;border-radius:12px 12px 12px 3px;padding:12px 14px;max-width:480px"></div><div class="hint" id="tplCount"></div></div>` : ''}</div>`;
}, after: () => commsPrev()};
function commsPrev(){ const el = document.getElementById('tplBody'); if(!el) return; const o = coll('orders').find(x => x.status !== 'cancelled' && activeG(x).some(gLive)) || coll('orders')[0]; const txt = fillMsg(el.value, msgCtx(o, o ? cust(o.customerId) : null, o ? activeG(o)[0] : null, {trial_date: fmtD(iso(addDays(new Date(), 3))) + ' 5:00 pm', amount: '5,000', receipt_no: 'RCPT-0012', alert_title: 'Delivery at risk', alert_detail: 'TD-1002/1 expected after delivery date'})); document.getElementById('tplPrev').textContent = txt; document.getElementById('tplCount').textContent = smsInfo(txt); }
function insPh(p){ const el = document.getElementById('tplBody'); if(!el) return; const s = el.selectionStart ?? el.value.length, e = el.selectionEnd ?? s; el.value = el.value.slice(0, s) + p + el.value.slice(e); el.focus(); el.selectionStart = el.selectionEnd = s + p.length; el.dispatchEvent(new Event('input', {bubbles: true})); }
function quickCompose(){ if(!coll('customers').length) return toast('Add a customer first', 'bad'); prompt2('New message', [{k: 'cid', label: 'Customer', type: 'select', options: coll('customers').slice().sort(by(c => c.name)).map(c => [c.id, c.name]), full: true}], x => { const os = coll('orders').filter(o => o.customerId === x.cid); if(!os.length) return openCompose(null, null, x.cid); prompt2('Which order?', [{k: 'oid', label: 'Order', type: 'select', options: [['', '— none —'], ...os.map(o => [o.id, o.no])], full: true}], y => openCompose(y.oid || null, null, x.cid), 'Continue'); }, 'Continue'); }

/* ---------------- setup ---------------- */
VIEWS.setup = {perm: 'setup', title: 'Setup', fn: () => {
  const tab = UI.stab || 'shop';
  const tabs = [['shop', 'Shop profile'], ['calendar', 'Calendar & targets'], ['qc', 'QC checklist'], ['billing', 'Billing heads'], ['users', 'Users & roles'], ['data', 'Data & backups']];
  return `<h1>Setup</h1><div class="sub">Changes save instantly.</div><div class="tabs">${tabs.map(([k, l]) => `<button class="${tab === k ? 'on' : ''}" onclick="UI.stab='${k}';render()">${l}</button>`).join('')}</div>${({shop: setShop, calendar: setCal, qc: setQC, billing: setHeads, users: setUsers, data: setData}[tab])()}`;
}, after: () => { if((UI.stab || 'shop') === 'users' && MODE === 'central') loadJoinReqs(); }};
const sIn = (p, lab, type, cls, ph) => `<div class="${cls || ''}"><label>${lab}</label><input type="${type || 'text'}" ${type === 'number' ? 'step="any"' : ''} data-root="DB" data-p="${p}" value="${v(getPath(DB, p))}" ${ph ? `placeholder="${h(ph)}"` : ''}></div>`;
function logoSrc(){ const l = ST().logo || ''; return l.startsWith('asset:') ? '/_blob/' + l.slice(6) : l; }
function setShop(){
  const s = ST();
  return `<div class="card"><div class="row ac" style="margin-bottom:12px"><div class="logo-box">${s.logo ? `<img src="${h(logoSrc())}" alt="Logo">` : '<span class="muted">No logo</span>'}</div><div><label class="btn sm" style="margin:0;color:var(--ink)">⬆ Upload logo<input type="file" accept="image/*" style="display:none" onchange="setLogo(this)"></label> ${s.logo ? `<button class="sm ghost danger" onclick="ST().logo='';save();render()">Remove</button>` : ''}<div class="hint">Shown in the menu, on invoices, receipts and job cards.</div></div></div>
  <div class="fgrid">${sIn('settings.shop', 'Shop name')}${sIn('settings.tagline', 'Tagline')}${sIn('settings.address', 'Address', 'text', 'full')}${sIn('settings.phone', 'Mobile / WhatsApp')}${sIn('settings.landline', 'Landline')}${sIn('settings.email', 'Email')}${sIn('settings.website', 'Website')}${sIn('settings.gstin', 'GST number (GSTIN)')}${sIn('settings.pan', 'PAN')}${sIn('settings.sac', 'SAC / HSN code')}${sIn('settings.upiId', 'UPI ID')}
  <div class="full"><label>Bank details (printed on invoices)</label><textarea rows="2" data-root="DB" data-p="settings.bank">${h(s.bank)}</textarea></div>
  ${sIn('settings.gstPct', 'Default GST %', 'number')}<div><label>Tax type</label><select data-root="DB" data-p="settings.taxMode">${opt('intra', 'CGST + SGST (same state)', s.taxMode)}${opt('inter', 'IGST (other state)', s.taxMode)}</select></div>${sIn('settings.markupPct', 'Default markup %', 'number')}${sIn('settings.orderPrefix', 'Order number prefix')}${sIn('settings.invPrefix', 'Invoice prefix')}${sIn('settings.rcptPrefix', 'Receipt prefix')}${sIn('settings.unit', 'Measurement unit')}
  <div class="full"><label>Invoice terms</label><textarea rows="2" data-root="DB" data-p="settings.terms">${h(s.terms)}</textarea></div>
  ${sIn('settings.adminName', 'Owner name (for alerts)')}${sIn('settings.adminPhone', 'Owner WhatsApp (alerts)')}${sIn('settings.adminEmail', 'Owner email')}</div>
  <div class="hint">Confirm the GST rate and SAC code for your services with your CA. A blank GSTIN prints a plain "Invoice".</div></div>`;
}
async function setLogo(inp){ const f = inp.files[0]; if(!f) return; try{ const b = await readImage(f, 360, 'image/png'); ST().logo = MODE === 'central' && SYNC.assets ? await mediaPut(b) : await blobToDataURL(b); save(); render(); toast('Logo updated', 'ok'); }catch(e){ toast('Logo: ' + e.message, 'bad'); } }
function setCal(){
  const s = ST();
  return `<div class="grid2"><div class="card"><h3>Shop calendar</h3><label>Weekly off</label><div>${['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map((d, i) => `<label class="inline"><input type="checkbox" ${(s.weeklyOff || []).includes(i) ? 'checked' : ''} onchange="toggleOff(${i},this.checked)"> ${d}</label>`).join('')}</div>
    <label style="margin-top:10px">Holidays (YYYY-MM-DD, comma separated)</label><textarea rows="3" data-root="DB" data-p="settings.holidays">${h(s.holidays)}</textarea><div class="hint">Worker-specific weekly offs and leave are set on each worker.</div></div>
  <div class="card"><h3>Default target dates — days before delivery</h3><div class="fgrid">${GROUPS.filter(([k]) => k !== 'delivery').map(([k, l]) => sIn('settings.lead.' + k, l, 'number')).join('')}</div><div class="hint">Stitching completion is targeted ${num(s.lead.stitching)} days before delivery. Each garment can override any target.</div></div></div>
  <div class="card"><h3>Alert thresholds</h3><div class="fgrid">${sIn('settings.warnDays', '"Approaching" = due within (days)', 'number')}${sIn('settings.overloadDays', 'Worker overloaded above (working days queued)', 'number')}${sIn('settings.overrunPct', 'Step overrun alert above estimate by (%)', 'number')}</div></div>`;
}
function toggleOff(d, on){ const w = new Set(ST().weeklyOff || []); on ? w.add(d) : w.delete(d); if(w.size >= 7) return toast('At least one working day is needed', 'bad'); ST().weeklyOff = [...w]; save(); render(); }
function setQC(){
  const CL = ST().qcChecklist;
  return `<div class="card"><div class="hint" style="margin-bottom:10px">Every QC uses this checklist. One item per line under each section.</div>${CL.map((sec, i) => `<div class="qc-sec"><div class="row ac"><input data-root="DB" data-p="settings.qcChecklist.${i}.sec" value="${v(sec.sec)}" style="max-width:260px;font-weight:600"><span class="sp"></span><button class="sm ghost danger" onclick="ST().qcChecklist.splice(${i},1);save();render()">Remove section</button></div><textarea rows="${sec.items.length + 1}" style="margin-top:6px" onchange="ST().qcChecklist[${i}].items=this.value.split('\\n').map(x=>x.trim()).filter(Boolean);save()">${h(sec.items.join('\n'))}</textarea></div>`).join('')}<button class="sm" onclick="ST().qcChecklist.push({sec:'New section',items:['Check item']});save();render()">+ Add section</button></div>`;
}
function setHeads(){
  return `<div class="grid2"><div class="card"><h3>Invoice charge heads</h3>${ST().heads.map((x, i) => `<div class="row ac" style="margin-bottom:6px"><span class="muted" style="width:120px;font-size:12px">${h(x.id)}</span><input data-root="DB" data-p="settings.heads.${i}.name" value="${v(x.name)}"></div>`).join('')}<div class="hint">These are the columns of the invoice's order-details table (in this order; only columns with an amount are printed). Rename freely; ids stay fixed. Work stages map to a head in Setup → Garment types → Stages.</div>
  <h3 style="margin-top:14px">Invoice footer</h3><label>Welcome / thank-you note</label><input data-root="DB" data-p="settings.invoiceFooter" value="${v(ST().invoiceFooter)}"><label style="margin-top:8px">Standard note (printed under Notes)</label><input data-root="DB" data-p="settings.invoiceNote" value="${v(ST().invoiceNote)}"><label style="margin-top:8px">Invoice number prefix</label><input data-root="DB" data-p="settings.invPrefix" value="${v(ST().invPrefix)}" style="max-width:140px"><div class="hint">GST is added only when a GST % is set on the order (Setup → Shop profile sets the default).</div></div>
  <div class="card"><h3>Material categories → charge head</h3>${(ST().categories || []).map((c, i) => `<div class="row ac" style="margin-bottom:6px"><input data-root="DB" data-p="settings.categories.${i}.name" value="${v(c.name)}"><select data-root="DB" data-p="settings.categories.${i}.head" style="max-width:220px">${ST().heads.map(x => opt(x.id, x.name, c.head)).join('')}</select></div>`).join('')}
  <h3 style="margin-top:14px">Embroidery styles (design catalogue)</h3><textarea rows="5" onchange="ST().embStyles=this.value.split('\\n').map(x=>x.trim()).filter(Boolean);save()">${h((ST().embStyles || []).join('\n'))}</textarea></div></div>`;
}
function setUsers(){
  const P = ST().perms || (ST().perms = defaultPerms());
  const matrix = `<div class="card"><h3>Role permissions</h3><div class="scroll"><table style="font-size:12.5px"><thead><tr><th>Permission</th>${Object.entries(ROLES).map(([k, l]) => `<th style="text-align:center">${h(l)}</th>`).join('')}</tr></thead><tbody>${PERMS.map(([p, l]) => `<tr><td>${h(l)}</td>${Object.keys(ROLES).map(r => `<td style="text-align:center"><input type="checkbox" ${r === 'owner' ? 'checked disabled' : ''} ${(P[r] || []).includes(p) ? 'checked' : ''} onchange="togglePerm('${r}','${p}',this.checked)"></td>`).join('')}</tr>`).join('')}</tbody></table></div><button class="sm" style="margin-top:8px" onclick="ST().perms=defaultPerms();save();render()">Reset to defaults</button></div>`;
  if(MODE === 'central'){
    const R = DB.access.roles || {};
    return `<div class="card"><h3>Staff accounts (central database)</h3><p class="muted" style="font-size:13px">Staff sign in with their own Claude account. Share this page with them as <b>Contributor</b> (Editors can also change setup), then assign a role here. People who open the page without a role see a "Request access" button; their requests appear below.</p>
    <div id="joinreqs" class="muted">Loading requests…</div>
    <table class="stack" style="margin-top:10px"><thead><tr><th>Person</th><th>Display name</th><th>Role</th><th>Linked worker</th><th></th></tr></thead><tbody id="rolerows">${Object.entries(R).map(([id, x]) => roleRow(id, x)).join('') || '<tr><td colspan="5" class="muted">No staff roles assigned yet.</td></tr>'}</tbody></table>
    <div class="hint">The page owner is always Owner. Role changes take effect the next time that person opens the page.</div></div>${matrix}`;
  }
  return `<div class="card"><h3>Staff logins on this device</h3><table class="ed stack"><thead><tr><th>Name</th><th>Role</th><th style="width:100px">PIN</th><th>Linked worker (for My tasks)</th><th>Active</th><th></th></tr></thead><tbody>${ST().users.map((u, i) => `<tr><td><input data-root="DB" data-p="settings.users.${i}.name" value="${v(u.name)}"></td><td><select data-root="DB" data-p="settings.users.${i}.role" ${u.id === 'u_owner' ? 'disabled' : ''}>${Object.entries(ROLES).map(([k, l]) => opt(k, l, u.role)).join('')}</select></td><td><input data-root="DB" data-p="settings.users.${i}.pin" value="${v(u.pin)}" inputmode="numeric"></td><td><select data-root="DB" data-p="settings.users.${i}.workerId">${opt('', '—', u.workerId)}${coll('workers').map(w => opt(w.id, w.name, u.workerId)).join('')}</select></td><td><input type="checkbox" data-root="DB" data-p="settings.users.${i}.active" ${u.active !== false ? 'checked' : ''} ${u.id === 'u_owner' ? 'disabled' : ''}></td><td>${u.id !== 'u_owner' ? `<button class="sm ghost danger" onclick="ST().users.splice(${i},1);save();render()">✕</button>` : ''}</td></tr>`).join('')}</tbody></table>
  <div class="row" style="margin-top:8px"><button class="sm" onclick="ST().users.push({id:uid('u'),name:'New user',role:'master',pin:String(Math.floor(1000+Math.random()*9000)),workerId:'',active:true});save();render()">+ Add user</button><label class="inline"><input type="checkbox" data-root="DB" data-p="settings.demoPins" ${ST().demoPins ? 'checked' : ''}> Show PINs on the login screen (demo only)</label></div>
  <div class="flag info" style="margin-top:10px">On a single device, PINs are a convenience lock. For secure separate logins across phones and computers, use the shared link — each person signs in with their own account and the central database enforces who can change setup.</div></div>${matrix}`;
}
function togglePerm(r, p, on){ const P = ST().perms; P[r] = P[r] || []; if(on){ if(!P[r].includes(p)) P[r].push(p); } else P[r] = P[r].filter(x => x !== p); save(); }
function roleRow(id, x){ return `<tr><td class="who-${h(id)}" data-uid="${h(id)}">…</td><td><input value="${v(x.label)}" onchange="DB.access.roles['${h(id)}'].label=this.value;save()"></td><td><select onchange="DB.access.roles['${h(id)}'].role=this.value;save()">${Object.entries(ROLES).filter(([k]) => k !== 'owner').map(([k, l]) => opt(k, l, x.role)).join('')}</select></td><td><select onchange="DB.access.roles['${h(id)}'].workerId=this.value;save()">${opt('', '—', x.workerId)}${coll('workers').map(w => opt(w.id, w.name, x.workerId)).join('')}</select></td><td><button class="sm ghost danger" onclick="delete DB.access.roles['${h(id)}'];save();render()">Remove</button></td></tr>`; }
async function loadJoinReqs(){
  const box = document.getElementById('joinreqs'); if(!box) return;
  try{
    const snap = await SYNC.db.collection('joinreq').get(), ids = snap.docs.map(d => d.id).filter(id => !(DB.access.roles || {})[id]);
    const all = [...new Set([...ids, ...Object.keys(DB.access.roles || {})])]; let names = {};
    try{ names = all.length ? await SYNC.user.profiles(all) : {}; }catch(e){}
    document.querySelectorAll('[data-uid]').forEach(td => { td.textContent = (names[td.dataset.uid] && names[td.dataset.uid].name) || 'Staff member ' + td.dataset.uid.slice(0, 6); });
    box.innerHTML = ids.length ? `<b>Access requests</b>${ids.map(id => `<div class="row ac" style="padding:6px 0;border-bottom:1px solid var(--line)"><span style="flex:1" data-n="${h(id)}"></span><select id="rq_${h(id)}" style="width:auto">${Object.entries(ROLES).filter(([k]) => k !== 'owner').map(([k, l]) => opt(k, l, 'master')).join('')}</select><button class="sm pri" onclick="grantRole('${h(id)}')">Grant</button><button class="sm ghost" onclick="SYNC.db.doc('joinreq/${h(id)}').delete().then(loadJoinReqs)">Dismiss</button></div>`).join('')}` : '<span class="muted">No pending access requests.</span>';
    box.querySelectorAll('[data-n]').forEach(el => el.textContent = (names[el.dataset.n] && names[el.dataset.n].name) || 'Someone (' + el.dataset.n.slice(0, 6) + ')');
  }catch(e){ box.textContent = 'Could not load requests (' + (e.code || e.message) + ').'; }
}
async function grantRole(id){ const sel = document.getElementById('rq_' + id), nm = sel.closest('.row').querySelector('[data-n]').textContent; DB.access.roles = DB.access.roles || {}; DB.access.roles[id] = {role: sel.value, label: nm, workerId: ''}; save(); try{ await SYNC.db.doc('joinreq/' + id).delete(); }catch(e){} render(); toast('Access granted', 'ok'); }
function setData(){
  const bk = DB.state.backups || [];
  return `<div class="grid2"><div class="card"><h3>Storage</h3>${MODE === 'central' ? '<p><b>Central database</b> — every device and staff member sees the same live data. Photos and sketches are stored centrally too.</p>' : '<p><b>This device only.</b> Open the shared link to use the central database across devices.</p>'}
    <h3 style="margin-top:12px">Export & import</h3><div class="row"><button onclick="exportData(false)">⬇ Export data (JSON)</button><button onclick="exportData(true)">⬇ Export with images</button><label class="btn" style="margin:0;color:var(--ink)">⬆ Import backup<input type="file" accept=".json" style="display:none" onchange="importData(this)"></label></div>
    <div class="row" style="margin-top:8px"><button onclick="exportAllCSV()">⬇ Orders & garments (CSV)</button><button onclick="exportCustomersCSV()">⬇ Customers & measurements (CSV)</button></div></div>
  <div class="card"><h3>Automatic backups</h3><p class="muted" style="font-size:13px">${MODE === 'central' ? 'A full backup is saved to the page\'s central file storage once a day when the owner opens the app (last 14 kept).' : 'A snapshot is saved in this browser once a day when the app opens (last 10 kept).'}</p>
    <div id="bklist">${MODE === 'central' ? (bk.length ? bk.slice().reverse().map(b => `<div class="row ac" style="padding:5px 0;border-bottom:1px solid var(--line)"><span style="flex:1">${fmtDT(b.at)} · ${(b.size / 1024).toFixed(0)} KB</span><button class="sm" onclick="restoreCentral('${h(b.id)}')">Restore</button></div>`).join('') : '<span class="muted">No backups yet.</span>') : '<span class="muted">Loading…</span>'}</div>
    <button class="sm" style="margin-top:8px" onclick="autoBackup(true)">Back up now</button></div></div>
  <div class="card"><h3>Reset</h3><div class="row">${MODE === 'local' ? '<button onclick="ask(\'Replace everything with fresh demo data?\',()=>{DB=seedDemo();migrate();save();render()})">Load demo data</button>' : ''}<button class="danger" onclick="clearTransactions()">Clear orders, customers & money records</button></div><div class="hint">Clearing keeps setup: garment types, workflows, stages, workers, vendors, stock items, designs and message presets.</div></div>`;
}
VIEWS.setup.after2 = null;
async function exportData(withMedia){
  const data = clone(DB); delete data.access;
  if(withMedia){ toast('Packing images…'); data._media = {}; const ids = new Set(); coll('designs').forEach(d => [...d.samples, ...(d.sketches || []), ...d.stencils, ...d.renders, ...d.spin, d.model].forEach(x => ids.add(x))); coll('garments').forEach(g => { (g.design?.versions || []).forEach(v2 => v2.files.forEach(f => ids.add(f.id))); (g.trials || []).forEach(t => (t.photos || []).forEach(p => ids.add(p))); });
    for(const id of ids){ if(!id || id.startsWith('demo:') || id.startsWith('data:')) continue; const b = await mediaBlob(id); if(b) data._media[id] = await blobToDataURL(b); } }
  await saveFile(`${slug(ST().shop)}-backup-${todayISO()}${withMedia ? '-with-images' : ''}.json`, JSON.stringify(data), 'application/json');
}
function importData(inp){
  const f = inp.files[0]; if(!f) return; const r = new FileReader();
  r.onload = () => { try{ const x = JSON.parse(r.result); if(!x.settings || !x.orders) throw new Error('Not a backup file'); ask('Replace all current data with this backup?', async () => { const media = x._media || {}; delete x._media; const acc = DB.access; DB = Object.assign(emptyDB(), x); DB.access = acc || {roles: {}}; migrate(); for(const [id, u] of Object.entries(media)){ const b = dataURLToBlob(u); if(MODE === 'central') { /* keep id mapping simple: store locally too */ } MEDIA.mem.set(id, b); await idbPut('files', id, b); } save(); render(); toast('Backup imported', 'ok'); }); }catch(e){ toast('Import failed: ' + e.message, 'bad'); } };
  r.readAsText(f); inp.value = '';
}
function clearTransactions(){ ask('Delete all orders, garments, customers, invoices, payments, ledgers, stock movements and messages? Setup is kept. This cannot be undone — export a backup first.', () => { ['customers', 'profiles', 'orders', 'garments', 'invoices', 'ledger', 'movements', 'custMaterials', 'msgLog'].forEach(c => DB[c] = []); DB.counters = {order: 1001, inv: 1, rcpt: 1}; DB.state.ack = {}; DB.state.notified = {}; save(); render(); toast('Cleared', 'ok'); }, 'Delete'); }
function exportAllCSV(){ const R = [['Garment no', 'Order no', 'Customer', 'Phone', 'Garment type', 'Title', 'Qty', 'Fabric', 'Status', 'Now at', 'Delivery date', 'Expected', 'Progress %', 'Price', 'Cost']]; const sc = sched(); coll('garments').forEach(g => { const o = ord(g.orderId), c = cust(g.customerId), b = garmentBill(g); R.push([g.no, o?.no, c?.name, c?.phone, tpl(g.tplId)?.name, g.title, g.qty, g.fabricSource, G_STATUS[gStatus(g)][0], gStageLabel(g), g.deliveryDate, sc.G[g.id]?.ready || '', progress(g).pct, can('prices') ? b.total : '', can('prices') ? b.cost : '']); }); saveCSV(`garments-${todayISO()}.csv`, R); }
function exportCustomersCSV(){ const R = [['Customer', 'Phone', 'Email', 'Profile', 'Garment type', 'Measurement', 'Value', 'Updated']]; coll('profiles').forEach(p => { const c = cust(p.customerId), t = tpl(p.tplId); (t?.fields || []).forEach(f => R.push([c?.name, c?.phone, c?.email, p.label, t.name, f.sec + ' · ' + f.label, p.values[f.k] ?? '', p.updated])); }); saveCSV(`customer-measurements-${todayISO()}.csv`, R); }
async function autoBackup(force){
  const today = todayISO();
  if(MODE === 'local'){
    if(!force && ST().lastBackup === today) return renderLocalBackups();
    await idbPut('backups', 'bk_' + nowISO(), JSON.stringify(DB)); ST().lastBackup = today; saveLocal();
    const keys = (await idbKeys('backups')).sort(); keys.slice(0, Math.max(0, keys.length - 10)).forEach(k => idbDel('backups', k));
    if(force) toast('Backup saved in this browser', 'ok'); return renderLocalBackups();
  }
  if(!SYNC.isOwner && !force) return; if(!SYNC.assets) { if(force) toast('Central file storage is not available for your role', 'bad'); return; }
  const bk = DB.state.backups || (DB.state.backups = []);
  if(!force && bk.length && bk[bk.length - 1].at.slice(0, 10) === today) return;
  try{ const json = JSON.stringify(DB), a = await SYNC.assets.upload(new Blob([json], {type: 'application/json'})); bk.push({id: a.id, at: nowISO(), size: json.length}); while(bk.length > 14){ const old = bk.shift(); try{ await SYNC.assets.delete(old.id); }catch(e){} } save(); if(force){ toast('Backup saved centrally', 'ok'); render(); } }
  catch(e){ if(force) toast('Backup failed: ' + (e.code || e.message), 'bad'); }
}
async function renderLocalBackups(){ const el = document.getElementById('bklist'); if(!el || MODE !== 'local') return; const keys = (await idbKeys('backups')).sort().reverse(); el.innerHTML = keys.length ? keys.map(k => `<div class="row ac" style="padding:5px 0;border-bottom:1px solid var(--line)"><span style="flex:1">${fmtDT(k.slice(3))}</span><button class="sm" onclick="restoreLocal('${h(k)}')">Restore</button></div>`).join('') : '<span class="muted">No backups yet.</span>'; }
function restoreLocal(k){ ask('Restore this backup? Current data is replaced (a backup of it is saved first).', async () => { await idbPut('backups', 'bk_' + nowISO(), JSON.stringify(DB)); const j = await idbGet('backups', k); DB = JSON.parse(j); migrate(); save(); render(); toast('Restored', 'ok'); }); }
function restoreCentral(id){ ask('Restore this central backup? Every device will see the restored data. A backup of the current data is taken first.', async () => { await autoBackup(true); try{ const r = await fetch('/_blob/' + id), x = await r.json(); const acc = DB.access, st = DB.state; DB = Object.assign(emptyDB(), x); DB.access = acc; DB.state = Object.assign(x.state || {}, {backups: st.backups}); migrate(); save(); render(); toast('Restored', 'ok'); }catch(e){ toast('Restore failed: ' + e.message, 'bad'); } }); }
VIEWS.setup.after = (() => { const prev = VIEWS.setup.after; return id => { prev && prev(id); if((UI.stab || 'shop') === 'data' && MODE === 'local') renderLocalBackups(); }; })();
